# find /etc/ssh -type f -name "ssh_host_*_key" -exec sh -c "chown -vv
root:wheel {}; chmod -vv 600 {}" \;

Run the following script to set mode, ownership, and group on the public SSH host key files:
# find /etc/ssh -type f -name "ssh_host_*_key.pub" -exec sh -c "chown -vv
root:wheel {}; chmod -vv 644 {}" \;

